module.exports = /*#__PURE__*/JSON.parse('{"home":{"heroTitle":"Coin किनीं आ बेचि","heroSubtitle":"P2P से आप दूसर लोग से सीधे coin के लेन-देन कर सकेनी। हमरा escrow आ विवाद समाधान प्रणाली हर ट्रेड के सुरक्षित बनावेला।","joinUs":"हमरा संगे जुड़ जाईं","statsCountries":"सहायता कइल गइल देश","statsPayments":"भुगतान तरीका","statsTime":"औसत ट्रेड समय","howItWorksTitle":"कइसे शुरू करीं","howItWorksSubtitle":"Paxones पर ट्रेडिंग आसान, सुरक्षित आ तेज बा। एह तीन आसान कदम के फॉलो करीं आ आपन P2P यात्रा शुरू करीं।","step1Title":"1. अकाउंट बनाई","step1Desc":"सिर्फ User ID से मुफ्त में साइन अप करीं। साधारण पहचान जाँच पूरा करीं ताकि अकाउंट सुरक्षित रहे आ ट्रेडिंग शुरू होखे।","step2Title":"2. ऑफर खोजीं","step2Desc":"दूसर यूजर के खरीद-बिक्री के विज्ञापन देखीं। Coin, भुगतान तरीका आ राशि से फिल्टर करीं आ सही मैच खोजीं।","step3Title":"3. ट्रेड शुरू करीं","step3Desc":"ट्रेड शुरू करीं आ सुरक्षित चैट के जरिए पार्टनर से बात करीं। सिक्योरिटी खातिर विक्रेता के coin escrow में लॉक हो जाला।","step4Title":"4. पूरा करीं आ पाएँ","step4Desc":"जब खरीदार भुगतान कर देला आ विक्रेता पुष्टि करेला, coin तुरते escrow से खरीदार के वॉलेट में रिलीज हो जाला।","whyP2PTitle":"P2P प्लेटफॉर्म पर ट्रेड काहे करीं?","whyP2PSubtitle":"P2P ट्रेडिंग पारंपरिक एक्सचेंज से अलग फायदा देला। सीधे दूसर लोग से ट्रेड करीं, आ आपन कीमत आ भुगतान तरीका पर पूरा कंट्रोल पाइए।","directTradingTitle":"सीधे ट्रेडिंग","directTradingDesc":"बीच वाला हटा दीं। आप सीधे दूसर आदमी से ट्रेड करीं, जे से बढ़िया रेट आ तेज़ लेन-देन हो सकेला।","globalPaymentsTitle":"ग्लोबल भुगतान तरीका","globalPaymentsDesc":"सैकड़ों भुगतान तरीका में से चुन सकतानी, लोकल बैंक ट्रांसफर, ऑनलाइन वॉलेट आ आउर बहुत कुछ, जवन कहीं से भी ट्रेड करना आसान बनावेला।","controlTitle":"आपके हाथ में कंट्रोल","controlDesc":"आपन खुद के कीमत तय करीं, आपन नियम बनाईं आ चुनल पार्टनर के साथ ट्रेड करीं। P2P आज के ट्रेडिंग प्लेटफॉर्म से अलग आजादी देला।","securityTitle":"आपके सुरक्षा हमरा प्राथमिकता","securitySubtitle":"हमनी के प्लेटफॉर्म बहु-लेयर सुरक्षा के साथ बनावल गइल बा ताकि हर ट्रेड शुरू से अंत तक सुरक्षित रहे।","escrowTitle":"सुरक्षित Escrow सिस्टम","escrowDesc":"जब ट्रेड शुरू होखेला, विक्रेता के coin सुरक्षित अस्थायी होल्डिंग (escrow) में ट्रांसफर हो जाला। फंड तबे रिलीज होला जब विक्रेता भुगतान के पुष्टि करेला। एह से धोखाधड़ी से बचाव होला।","disputeTitle":"विवाद समाधान","disputeDesc":"कबहूँ विवाद होखे पर, हमरा सपोर्ट टीम मदद खातिर बा। मोडरेटर ट्रेड डिटेल, चैट लॉग आ भुगतान प्रमाण देख के निष्पक्ष फैसला करेला।","supportedCoinsTitle":"सपोर्टेड Coins","supportedCoinsDesc":"हमनी के लोकप्रिय डिजिटल संपत्ति के बढ़त सूची सपोर्ट कर रहल बानी, आ लगातार नया coin जोड़ल जा रहल बा।"},"buySellForm":{"buyTab":"हम खरीदब","sellTab":"हम बेचब","haveLabel":"हमरा लगे बा","wantLabel":"हम चाहतानी","coinLabel":"Coin","amountPlaceholder":"राशि डालि","paymentMethodLabel":"भुगतान तरीका","allPaymentMethods":"सब भुगतान तरीका","findOffers":"ऑफर खोजीं","getApprox":"आप लगभग पाइब","payApprox":"आप लगभग देब"},"homeSignupForm":{"placeholder":"आपन User ID चुनीं"},"footer":{"tagline":"आत्मविश्वास से ट्रेड करीं। Paxones विश्वसनीय एस्क्रो सिस्टम के साथ एगो सुरक्षित P2P प्लेटफॉर्म उपलब्ध करावेला।","company":"कंपनी","about":"हमरा बारे में","careers":"करियर","press":"प्रेस","legal":"कानूनी","terms":"सेवा के नियम","privacy":"गोपनीयता नीति","aml":"AML नीति","support":"सहायता","contact":"संपर्क करीं","faq":"FAQ","dispute":"विवाद समाधान","copyright":"सभी अधिकार सुरक्षित।"}}');

