module.exports = /*#__PURE__*/JSON.parse('{"home":{"heroTitle":"Mua và bán tiền điện tử","heroSubtitle":"Giao dịch P2P cho phép bạn giao dịch trực tiếp với người khác. Hệ thống ký quỹ và giải quyết tranh chấp của chúng tôi đảm bảo mọi giao dịch đều được bảo vệ.","joinUs":"Tham gia ngay","statsCountries":"Quốc gia hỗ trợ","statsPayments":"Phương thức thanh toán","statsTime":"Thời gian giao dịch trung bình","howItWorksTitle":"Cách bắt đầu","howItWorksSubtitle":"Giao dịch trên Paxones đơn giản, an toàn và nhanh chóng. Làm theo ba bước dễ dàng dưới đây để bắt đầu hành trình P2P của bạn.","step1Title":"1. Tạo tài khoản","step1Desc":"Đăng ký miễn phí chỉ với ID người dùng. Hoàn thành xác minh danh tính đơn giản để bảo vệ tài khoản và bắt đầu giao dịch.","step2Title":"2. Tìm giao dịch","step2Desc":"Duyệt các quảng cáo mua hoặc bán từ người dùng khác. Lọc theo đồng coin, phương thức thanh toán và số tiền để tìm giao dịch phù hợp nhất.","step3Title":"3. Bắt đầu giao dịch","step3Desc":"Khởi tạo giao dịch và liên lạc với đối tác qua chat bảo mật của chúng tôi. Coin của người bán sẽ được khóa trong ký quỹ để đảm bảo an toàn.","step4Title":"4. Hoàn tất và nhận","step4Desc":"Khi người mua thanh toán và người bán xác nhận, coin sẽ được giải phóng ngay lập tức từ ký quỹ vào ví của người mua.","whyP2PTitle":"Tại sao giao dịch trên nền tảng P2P?","whyP2PSubtitle":"Giao dịch P2P mang lại lợi thế độc đáo so với sàn truyền thống. Giao dịch trực tiếp với người khác, cho phép bạn kiểm soát giá và phương thức thanh toán.","directTradingTitle":"Giao dịch trực tiếp","directTradingDesc":"Loại bỏ trung gian. Bạn thương lượng và giao dịch trực tiếp với người khác, giúp có giá tốt hơn và giao dịch nhanh hơn.","globalPaymentsTitle":"Phương thức thanh toán toàn cầu","globalPaymentsDesc":"Chọn từ hàng trăm phương thức thanh toán, bao gồm chuyển khoản ngân hàng địa phương, ví điện tử và hơn thế nữa, dễ dàng giao dịch từ bất cứ đâu.","controlTitle":"Bạn hoàn toàn kiểm soát","controlDesc":"Đặt giá của riêng bạn, xác định điều khoản và chọn đối tác giao dịch. P2P mang đến sự tự do mà các nền tảng truyền thống không có.","securityTitle":"Bảo mật là ưu tiên hàng đầu","securitySubtitle":"Chúng tôi thiết kế nền tảng với nhiều lớp bảo mật để đảm bảo mọi giao dịch được bảo vệ từ đầu đến cuối.","escrowTitle":"Hệ thống ký quỹ an toàn","escrowDesc":"Khi giao dịch bắt đầu, coin của người bán sẽ được tự động chuyển vào kho lưu trữ tạm thời (ký quỹ) an toàn. Quỹ chỉ được giải phóng khi người bán xác nhận đã nhận thanh toán, ngăn ngừa gian lận.","disputeTitle":"Giải quyết tranh chấp","disputeDesc":"Trong trường hợp hiếm có tranh chấp, đội ngũ hỗ trợ chuyên dụng của chúng tôi sẽ giúp đỡ. Các nhà điều hành sẽ kiểm tra chi tiết giao dịch, lịch sử chat và bằng chứng thanh toán để đưa ra quyết định công bằng.","supportedCoinsTitle":"Các loại coin hỗ trợ","supportedCoinsDesc":"Chúng tôi hỗ trợ danh sách các tài sản kỹ thuật số phổ biến và liên tục thêm coin mới."},"buySellForm":{"buyTab":"Tôi muốn mua","sellTab":"Tôi muốn bán","haveLabel":"Tôi có","wantLabel":"Tôi muốn","coinLabel":"Coin","amountPlaceholder":"Nhập số tiền","paymentMethodLabel":"Phương thức thanh toán","allPaymentMethods":"Tất cả phương thức thanh toán","findOffers":"Tìm giao dịch","getApprox":"Bạn sẽ nhận khoảng","payApprox":"Bạn sẽ trả khoảng"},"homeSignupForm":{"placeholder":"Chọn ID người dùng"},"footer":{"tagline":"Tự tin giao dịch. Paxones cung cấp một nền tảng P2P an toàn với hệ thống ký quỹ đáng tin cậy.","company":"Công ty","about":"Về chúng tôi","careers":"Tuyển dụng","press":"Báo chí","legal":"Pháp lý","terms":"Điều khoản dịch vụ","privacy":"Chính sách bảo mật","aml":"Chính sách AML","support":"Hỗ trợ","contact":"Liên hệ","faq":"Câu hỏi thường gặp","dispute":"Giải quyết tranh chấp","copyright":"Bản quyền tất cả các quyền."}}');

